DO $change$ DECLARE body text;BEGIN SELECT pg_get_functiondef('public.pipeline_candidate_action(text,text,jsonb)'::regprocedure) INTO body;body:=replace(body,'IF command=''demographic'' THEN INSERT','IF command=''demographic'' THEN IF a.status NOT IN (''submitted'',''scored'') THEN RAISE EXCEPTION ''Optional fairness information is available after submission'';END IF;INSERT');EXECUTE body;END $change$;